package bo.com.ganadero.alertas.api;import bo.com.ganadero.alertas.application.*;import bo.com.ganadero.alertas.domain.*;import bo.com.ganadero.shared.api.ApiResponse;import bo.com.ganadero.shared.web.CorrelationIdFilter;import jakarta.servlet.http.HttpServletRequest;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/alertas")public class AlertaController{private final AlertaQueryService s;public AlertaController(AlertaQueryService s){this.s=s;}@GetMapping ApiResponse<List<Alerta>>listar(@RequestParam(required=false)EstadoAlerta estado,@RequestParam(required=false)TipoAlerta tipo,@RequestParam(required=false)UUID animalId,HttpServletRequest r){return ok(s.listar(estado,tipo,animalId),r);}@GetMapping("/{id}")ApiResponse<Alerta>obtener(@PathVariable UUID id,HttpServletRequest r){return ok(s.obtener(id),r);}@GetMapping("/no-leidas/count")ApiResponse<AlertaQueryService.ConteoAlertas>count(HttpServletRequest r){return ok(s.noLeidas(),r);}@GetMapping("/resumen")ApiResponse<AlertaQueryService.ResumenAlertas>resumen(HttpServletRequest r){return ok(s.resumen(),r);}@PostMapping("/{id}/atender")ApiResponse<Alerta>atender(@PathVariable UUID id,HttpServletRequest r){return ok(s.atender(id),r);}@PostMapping("/{id}/resolver")ApiResponse<Alerta>resolver(@PathVariable UUID id,HttpServletRequest r){return ok(s.resolver(id),r);}@PostMapping("/procesar-vencidas")ApiResponse<Integer>procesar(@RequestParam(defaultValue="100")int limite,HttpServletRequest r){return ok(s.procesarVencidas(limite),r);}private<T>ApiResponse<T>ok(T d,HttpServletRequest r){Object c=r.getAttribute(CorrelationIdFilter.ATTRIBUTE);return ApiResponse.success(d,c==null?"unknown":c.toString());}}
